// NewUpsertConfigPayload builds a deviceIntegrations service upsertConfig
// endpoint payload.
func NewUpsertConfigPayload(body *UpsertConfigRequestBody, apikeyToken *string, sessionToken *string) *deviceintegrations.UpsertConfigPayload {
	v := &deviceintegrations.UpsertConfigPayload{
		Provider: *body.Provider,
		Enabled:  *body.Enabled,
	}
	if body.Credentials != nil {
		v.Credentials = make(map[string]string, len(body.Credentials))
		for key, val := range body.Credentials {
			tk := key
			tv := val
			v.Credentials[tk] = tv
		}
	}
	if body.Settings != nil {
		v.Settings = make(map[string]string, len(body.Settings))
		for key, val := range body.Settings {
			tk := key
			tv := val
			v.Settings[tk] = tv
		}
	}
	v.ApikeyToken = apikeyToken
	v.SessionToken = sessionToken

	return v
}

